function restore(){try{const s=JSON.parse(localStorage.getItem(STORAGE));if(s&&Array.isArray(s.stations))return s}catch(e){}return {stations:DEFAULTS,currentId:DEFAULTS[0].id,volume:65}}
const state=restore();
state.stations=state.stations.filter(s=>s&&typeof s.url==='string'&&typeof s.name==='string');

state.volume=Number.isFinite(+state.volume)?Math.min(100,Math.max(0,+state.volume)):65;
