function somaSlug(station){if(!station)return '';try{const host=new URL(station.url).hostname.toLowerCase();if(!host.endsWith('somafm.com'))return '';const path=new URL(station.url).pathname.slice(1).split('/')[0];const token=path.split('-')[0];return SOMA_SLUGS[token]||''}catch(e){return ''}}
function clock(seconds, hours=false){let n=Math.max(0,Math.floor(seconds));const h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=n%60;const p=v=>String(v).padStart(2,'0');return hours||h?p(h)+':'+p(m)+':'+p(s):p(m)+':'+p(s)}
function resetTrackInfo(stationId){listenStationId=stationId||null;listeningSeconds=0;listenTick=Date.now();songKey='';songDetectedAt=0;songDuration=0;metadataSerial++;if(metaAbort){metaAbort.abort();metaAbort=null}if(metaInterval){clearInterval(metaInterval);metaInterval=null}$('trackTitle').textContent=tr('track_unavailable');$('trackArtist').hidden=true;$('trackArtist').textContent='';updateTrackDisplay()}
let metaInterval=null;
function trackFromSoma(data){const list=Array.isArray(data)?data:Array.isArray(data?.songs)?data.songs:Array.isArray(data?.songlist)?data.songlist:[];const entry=list[0]||data?.song||data?.nowplaying||data?.current||null;if(!entry||typeof entry!=='object')return null;const artist=String(entry.artist||'').trim(),title=String(entry.title||entry.song||'').trim();if(!title)return null;const key=artist+'|'+title;let duration=Number(entry.duration||entry.length||0);if(!Number.isFinite(duration)||duration<0||duration>36000)duration=0;
// Only use explicit start timestamps when present. Otherwise count from first observation.
const rawTime=entry.played_at||entry.started_at||entry.start_time;let start=rawTime?Date.parse(rawTime):NaN;if(!Number.isFinite(start)&&Number.isFinite(+rawTime)&&+rawTime>1000000000)start=+rawTime<1e12?+rawTime*1000:+rawTime;return {key,title,artist,duration,start};}
function updateTrackDisplay(){const on=playing&&!audio.paused;const seconds=on&&songDetectedAt?Math.max(0,Math.floor((Date.now()-songDetectedAt)/1000)):0;$('trackElapsed').textContent=songKey?clock(seconds):'00:00';$('trackDuration').textContent=songDuration?clock(songDuration):(I18N[language]?.track_live||I18N.en.track_live);$('trackFill').style.width=songDuration?Math.min(100,(seconds/songDuration)*100)+'%':'0%';$('listeningClock').textContent=clock(listeningSeconds,true)}
function applyTrackMetadata(entry,serial){if(serial!==metadataSerial||!entry)return;if(songKey!==entry.key){songKey=entry.key;songDetectedAt=Number.isFinite(entry.start)&&entry.start<=Date.now()&&entry.start>Date.now()-24*3600000?entry.start:Date.now();songDuration=entry.duration;$('trackTitle').textContent=entry.title;$('trackArtist').textContent=entry.artist;$('trackArtist').hidden=!entry.artist}updateTrackDisplay()}
async function loadSomaMetadata(serial,slug){if(serial!==metadataSerial||!playing||audio.paused)return;if(metaAbort)metaAbort.abort();const controller=new AbortController();metaAbort=controller;const timeout=setTimeout(()=>controller.abort(),6000);try{const response=await fetch('https://somafm.com/songs/'+encodeURIComponent(slug)+'.json',{signal:controller.signal,cache:'no-store'});if(!response.ok)throw Error('metadata');const data=await response.json();applyTrackMetadata(trackFromSoma(data),serial)}catch(e){/* CORS/unavailable: keep timer and fallback */}finally{clearTimeout(timeout);if(metaAbort===controller)metaAbort=null}}
