function toast(message){const box=$('toast');box.textContent=message;box.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.classList.remove('show'),4000)}
function current(){return state.stations.find(s=>s.id===state.currentId)||state.stations[0]}
function setStatus(message){$('playerStatus').textContent=message;const key=Object.keys(I18N[language]).find(k=>I18N[language][k]===message);$('playerStatus').dataset.statusKey=key||''}
// Hero artwork: use station logos where available; preserve the original radio symbol as fallback.
let heroLogoRequest=0;
const heroLogoCache=new Map();
function applyHeroLogo(url, stationName, request){
  if(request!==heroLogoRequest)return;
  const img=$('orbLogo'),fallback=$('orbFallback');
  const valid=safeUrl(url);
  if(!valid || (location.protocol==='https:' && !valid.startsWith('https:'))){
    img.hidden=true;img.removeAttribute('src');fallback.hidden=false;return;
  }
  const test=new Image();
  test.referrerPolicy='no-referrer';
  test.onload=()=>{if(request!==heroLogoRequest)return;img.src=valid;img.alt=stationName;img.hidden=false;fallback.hidden=true;};
  test.onerror=()=>{if(request!==heroLogoRequest)return;img.hidden=true;img.removeAttribute('src');fallback.hidden=false;};
  test.src=valid;
}
function updateHeroLogo(station){
  const request=++heroLogoRequest;
  $('orbLogo').hidden=true;$('orbLogo').removeAttribute('src');$('orbFallback').hidden=false;
  if(!station)return;
  if(station.logo && safeUrl(station.logo)){
    applyHeroLogo(station.logo,station.name,request);return;
  }
  const name=station.name.trim();
  if(!name)return;
  if(heroLogoCache.has(name)){
    applyHeroLogo(heroLogoCache.get(name),name,request);return;
  }
  // Name-based lookup is best-effort, never blocks audio playback.
  const url='https://de1.api.radio-browser.info/json/stations/byname/'+encodeURIComponent(name)+'?limit=20&hidebroken=true';
  fetch(url).then(r=>{if(!r.ok)throw Error('directory');return r.json()}).then(items=>{
    const normalize=x=>String(x||'').trim().toLocaleLowerCase();
    const match=Array.isArray(items)?items.find(s=>normalize(s.name)===normalize(name)&&safeUrl(s.favicon)?.startsWith('https:')):null;
    const logo=match?.favicon||'';
    heroLogoCache.set(name,logo);
    applyHeroLogo(logo,name,request);
  }).catch(()=>{heroLogoCache.set(name,'');applyHeroLogo('',name,request)});
}
let heroShownKey=null;
function updateNow(){const s=current();const heroKey=s?(s.id+'|'+(s.logo||'')+'|'+s.name):'';if(heroKey!==heroShownKey){heroShownKey=heroKey;updateHeroLogo(s)}$('heroArt').classList.toggle('is-playing',playing&&!audio.paused);$('currentTitle').textContent=s?s.name:tr('nostations');$('currentGenre').textContent=s?(s.genre||'Internet Radio'):tr('addfirst');$('qualityLabel').textContent=tr('internet_radio')+' · LIVE';document.title=(s?s.name+' · ':'')+'JARVIS RADIO';const show=playing&&!audio.paused;$('playIcon').setAttribute('href',show?'#i-pause':'#i-play');$('playBtn').classList.toggle('is-playing',show);$('playBtn').setAttribute('aria-label',show?tr('pause'):tr('play'));$('audioBars').classList.toggle('playing',show);if('mediaSession' in navigator && s){try{navigator.mediaSession.metadata=new MediaMetadata({title:s.name,artist:s.genre||'Internet Radio',album:'JARVIS RADIO',artwork:s.logo?[{src:s.logo}]:[]});navigator.mediaSession.playbackState=show?'playing':'paused'}catch(e){}}}
function stop(){audio.pause();audio.removeAttribute('src');audio.load();playing=false;setStatus(tr('stopped'));updateNow()}
async function play(id){let s=state.stations.find(x=>x.id===id);if(!s)return toast(tr('notfound'));const changed=state.currentId!==id||audio.dataset.station!==id||!audio.getAttribute('src');state.currentId=id;if(listenStationId!==id)resetTrackInfo(id);save();if(changed){audio.pause();audio.src=s.url;audio.dataset.station=id;audio.dataset.backupTried='0'}playing=true;setStatus(tr('connecting'));updateNow();render();try{await audio.play();setStatus(tr('live'))}catch(e){playing=false;setStatus(tr('failed'));toast(tr('stream_blocked'));updateNow()}}
function toggle(){if(!current())return toast(tr('add_first'));if(!audio.paused){audio.pause();playing=false;setStatus(tr('paused'));updateNow()}else play(state.currentId)}
function switchStation(step){const arr=state.stations;if(!arr.length)return;let i=arr.findIndex(s=>s.id===state.currentId);play(arr[(i+step+arr.length)%arr.length].id)}
function safeUrl(url){try{const u=new URL(url);return u.protocol==='https:'||u.protocol==='http:'?u.href:''}catch(e){return ''}}
function createStationCard(s,fromDirectory=false){const card=document.createElement('article');card.className='station-card'+(!fromDirectory&&s.id===state.currentId?' current':'');const art=document.createElement('div');art.className='station-art';if(s.logo&&safeUrl(s.logo)){const img=document.createElement('img');img.loading='lazy';img.alt='';img.referrerPolicy='no-referrer';img.src=s.logo;img.onerror=()=>{img.remove();art.innerHTML=icon('radio')};art.append(img)}else art.innerHTML=icon('radio');card.append(art);
const main=document.createElement('div');main.className='station-main';const name=document.createElement('span');name.className='station-name';name.textContent=s.name;name.title=s.name;const genre=document.createElement('span');genre.className='station-genre';genre.textContent=s.genre||'Internet Radio';main.append(name,genre);main.addEventListener('click',()=>fromDirectory?addDirectoryStation(s,true):play(s.id));card.append(main);
const controls=document.createElement('div');controls.className='station-controls';const exists=state.stations.find(x=>x.url===s.url||x.id===s.id);
if(fromDirectory){const add=document.createElement('button');add.className='mini-btn primary';add.title=exists?tr('in_collection'):tr('add_collection');add.setAttribute('aria-label',add.title);add.innerHTML=exists?'✓':icon('plus');add.disabled=!!exists;add.addEventListener('click',()=>addDirectoryStation(s,false));controls.append(add)}else{
const fav=document.createElement('button');fav.className='mini-btn'+(s.favorite?' is-fav':'');fav.title=s.favorite?tr('remove_fav'):tr('to_fav');fav.setAttribute('aria-label',fav.title);fav.innerHTML=icon('heart');fav.addEventListener('click',()=>{s.favorite=!s.favorite;save();render()});controls.append(fav);
const edit=document.createElement('button');edit.className='mini-btn';edit.title=tr('edit');edit.setAttribute('aria-label',edit.title);edit.innerHTML=icon('edit');edit.addEventListener('click',()=>openDialog(s));controls.append(edit);
const del=document.createElement('button');del.className='mini-btn danger';del.title=tr('delete');del.setAttribute('aria-label',del.title);del.innerHTML=icon('trash');del.addEventListener('click',()=>{if(confirm(tr('delete_confirm',{name:s.name}))){const wasCurrent=state.currentId===s.id;state.stations=state.stations.filter(x=>x.id!==s.id);if(wasCurrent){stop();state.currentId=state.stations[0]?.id||null}save();render();updateNow()}});controls.append(del);
const p=document.createElement('button');p.className='mini-btn primary';p.title=tr('listen');p.setAttribute('aria-label',tr('listen_named',{name:s.name}));p.innerHTML=icon('play');p.addEventListener('click',()=>play(s.id));controls.append(p)}
card.append(controls);return card}
function render(){const query=$('searchInput').value.trim().toLocaleLowerCase();let list=tab==='directory'?directory:tab==='featured'?FEATURED.filter(s=>featureGroup==='all'||s.group.split(' ').includes(featureGroup)):state.stations.filter(s=>tab==='all'||s.favorite);if(query&&tab!=='directory')list=list.filter(s=>(s.name+' '+s.genre).toLocaleLowerCase().includes(query));$('stationCount').textContent=state.stations.length;$('sectionEyebrow').textContent=tab==='directory'?tr('directory_label'):tab==='featured'?tr('featured_label'):tab==='favorite'?tr('fav_label'):tr('collection');$('sectionTitle').firstChild.textContent=tab==='directory'?tr('directory_title'):tab==='featured'?tr('featured'):tab==='favorite'?tr('favorites'):tr('my');$('listCount').textContent='('+list.length+')';$('addBtn').hidden=tab==='directory'||tab==='featured';$('reloadBtn').hidden=tab!=='directory';$('searchInput').placeholder=tab==='directory'?tr('search_world'):tab==='featured'?tr('search_featured'):tr('search_mine');$('featuredFilters').hidden=tab!=='featured';$('directoryFilters').hidden=tab!=='directory';const listEl=$('stationList');listEl.replaceChildren();list.forEach(s=>listEl.append(createStationCard(s,tab==='directory'||tab==='featured')));const empty=$('emptyState');empty.hidden=!!list.length;empty.textContent=(tab==='directory'||tab==='featured')?tr('empty_search'):tab==='favorite'?tr('empty_fav'):query?tr('empty_query'):tr('empty_collection');$('loadMoreWrap').hidden=tab!=='directory'||!directoryHasMore;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));}
function setTab(t){tab=t;$('searchInput').value='';directory=[];directoryPage=0;directoryHasMore=false;render();if(t==='directory')searchDirectory();}
function openDialog(s=null){editingId=s?.id||null;$('dialogTitle').textContent=s?tr('edit'):tr('add');$('stationName').value=s?.name||'';$('stationUrl').value=s?.url||'';$('stationGenre').value=s?.genre||'';$('stationLogo').value=s?.logo||'';$('stationBackup').value=s?.backup||'';$('stationDialog').showModal()}
function closeDialog(){$('stationDialog').close()}
function addDirectoryStation(s,autoplay){const existing=state.stations.find(x=>x.url===s.url);if(existing){if(autoplay)play(existing.id);else toast(tr('already'));return}const item={id:newStationId(),name:s.name,url:s.url,genre:s.genre,logo:s.logo||'',backup:s.backup||'',favorite:false,source:'directory'};state.stations.push(item);save();toast(tr('added_named',{name:s.name}));render();if(autoplay)play(item.id)}
// Radio Browser public catalogue: use fallback mirrors when a server is unreachable.
const MIRRORS=['https://de1.api.radio-browser.info','https://nl1.api.radio-browser.info','https://at1.api.radio-browser.info'];
async function searchDirectory(next=false){const q=$('searchInput').value.trim();const page=next?directoryPage+1:0;const request=++searchCounter;if(!next){directory=[];directoryHasMore=false;render()}setStatus(playing?tr('live'):tr('searching'));const params=new URLSearchParams({hidebroken:'true',order:'clickcount',reverse:'true',limit:'24',offset:String(page*24)});if(q)params.set('name',q);if($('countryFilter').value)params.set('countrycode',$('countryFilter').value);if($('genreFilter').value)params.set('tag',$('genreFilter').value);const endpoints=MIRRORS.map(m=>m+'/json/stations/search?'+params);let data=null;for(const endpoint of endpoints){try{const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),6500);let response;try{response=await fetch(endpoint,{signal:controller.signal,headers:{Accept:'application/json'}})}finally{clearTimeout(timeout)}if(!response.ok)throw new Error('HTTP '+response.status);data=await response.json();break}catch(e){continue}}
if(request!==searchCounter)return;if(!data){if(!next){directory=[];directoryHasMore=false}toast(tr('catalog_fail'));render();return}const stations=data.filter(s=>s&&s.name&&safeUrl(s.url_resolved||s.url)&&(!$('httpsOnly').checked||(s.url_resolved||s.url).startsWith('https://'))).map(s=>({id:s.stationuuid||newStationId(),name:s.name.trim(),url:s.url_resolved||s.url,genre:[s.tags?.split(',').slice(0,2).join(' · '),s.country].filter(Boolean).join(' · ').slice(0,90),logo:s.favicon||''}));directory=next?directory.concat(stations):stations;directoryPage=page;directoryHasMore=data.length===24;render();if(!playing)setStatus(tr('ready'))}
$('playBtn').addEventListener('click',toggle);$('prevBtn').addEventListener('click',()=>switchStation(-1));$('nextBtn').addEventListener('click',()=>switchStation(1));
$('volume').addEventListener('input',e=>{state.volume=Number(e.target.value);audio.volume=state.volume/100;audio.muted=false;$('volumeValue').textContent=state.volume+'%';$('volumeIcon').setAttribute('href',state.volume===0?'#i-mute':'#i-volume');save()});$('muteBtn').addEventListener('click',()=>{audio.muted=!audio.muted;$('volumeIcon').setAttribute('href',audio.muted?'#i-mute':'#i-volume')});
$('addBtn').addEventListener('click',()=>openDialog());$('addTop').addEventListener('click',()=>openDialog());$('closeDialog').addEventListener('click',closeDialog);$('cancelDialog').addEventListener('click',closeDialog);
$('stationForm').addEventListener('submit',e=>{e.preventDefault();const name=$('stationName').value.trim(),url=safeUrl($('stationUrl').value.trim()),genre=$('stationGenre').value.trim(),logo=$('stationLogo').value.trim(),backup=$('stationBackup').value.trim();if(!name||!url)return toast(tr('invalid_url'));if(backup&&!safeUrl(backup))return toast(tr('invalid_backup'));if(logo&&!safeUrl(logo))return toast(tr('invalid_logo'));const duplicate=state.stations.find(s=>s.url===url&&s.id!==editingId);if(duplicate)return toast(tr('duplicate'));if(editingId){const s=state.stations.find(s=>s.id===editingId);if(s){const changedUrl=s.url!==url;Object.assign(s,{name,url,genre,logo,backup});if(changedUrl&&state.currentId===s.id)stop();}}else{const item={id:newStationId(),name,url,genre,logo,backup,favorite:false,source:'user'};state.stations.push(item);if(!state.currentId)state.currentId=item.id}save();closeDialog();render();updateNow();toast(tr('saved'))});
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.tab)));document.querySelectorAll('[data-feature]').forEach(b=>b.addEventListener('click',()=>{featureGroup=b.dataset.feature;document.querySelectorAll('[data-feature]').forEach(x=>x.classList.toggle('active',x===b));render()}));['countryFilter','genreFilter','httpsOnly'].forEach(id=>$(id).addEventListener('change',()=>{if(tab==='directory')searchDirectory()}));
$('searchInput').addEventListener('input',()=>{if(tab!=='directory'){render();return}clearTimeout(searchTimer);searchTimer=setTimeout(()=>searchDirectory(),450)});$('reloadBtn').addEventListener('click',()=>searchDirectory());$('loadMoreBtn').addEventListener('click',()=>searchDirectory(true));
audio.addEventListener('playing',()=>{playing=true;setStatus(tr('live'));updateNow();startTrackLookup()});audio.addEventListener('waiting',()=>{if(playing)setStatus(tr('buffering'))});audio.addEventListener('error',()=>{const s=current();if(playing&&s?.backup&&audio.dataset.backupTried!=='1'){audio.dataset.backupTried='1';audio.src=s.backup;setStatus(tr('backup_try'));audio.play().catch(()=>{});return}playing=false;setStatus(tr('audio_error'));updateNow();if(audio.dataset.station)toast(tr('stream_error'))});audio.addEventListener('pause',()=>{if(!audio.ended){playing=false;updateNow()}});audio.addEventListener('ended',()=>{playing=false;setStatus(tr('ended'));updateNow()});
if('mediaSession' in navigator){try{navigator.mediaSession.setActionHandler('play',()=>toggle());navigator.mediaSession.setActionHandler('pause',()=>{audio.pause();playing=false;updateNow()});navigator.mediaSession.setActionHandler('previoustrack',()=>switchStation(-1));navigator.mediaSession.setActionHandler('nexttrack',()=>switchStation(1));navigator.mediaSession.setActionHandler('stop',stop)}catch(e){}}
function network(){const online=navigator.onLine;$('networkLabel').textContent=online?tr('online'):tr('offline');document.querySelector('.connected-dot').style.background=online?'#39d69e':'#e99b5e'}window.addEventListener('online',network);window.addEventListener('offline',network);network();
const bars=$('audioBars');for(let i=0;i<22;i++){const b=document.createElement('i');b.style.setProperty('--h',(7+Math.abs(Math.sin(i*1.39))*27)+'px');b.style.setProperty('--delay',(-i*.07)+'s');b.style.setProperty('--speed',(i%5)*.14+'s');bars.append(b)}
